import sympy

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def has_roots_mod_p(f, p):
    # Compute the Legendre symbol (p|f(x))
    legendre_symbol = pow(f.subs('x', 1), (p - 1) // 2, p)
    return legendre_symbol == 1

def solve_problem():
    for p in range(7, 100):  # Check for primes up to 100
        if is_prime(p) and p > 3:
            f = sympy.symbols('x')**2 + 3*sympy.symbols('x') + 3
            if has_roots_mod_p(f, p):
                print(f'p = {p} has roots mod p')
            else:
                print(f'p = {p} does not have roots mod p')

solve_problem()
